static inline void LOGO_DRAW(
    int16_t offsetX,
    int16_t offsetY,
    int16_t scaleX = 1,
    int16_t scaleY = 1)
{
    uint_farptr_t boxesAddress = pgm_get_far_address(LOGOBoxes);
    uint_farptr_t paletteAddress = pgm_get_far_address(LOGOPalette);

    for (uint16_t i = 0; i < LOGO_BOX_COUNT; i++)
    {
        uint_farptr_t address = boxesAddress + i * 5 * sizeof(uint8_t);

        uint8_t x          = pgm_read_byte_far(address + 0);
        uint8_t y          = pgm_read_byte_far(address + 1);
        uint8_t width      = pgm_read_byte_far(address + 2);
        uint8_t height     = pgm_read_byte_far(address + 3);
        uint8_t colorIndex = pgm_read_byte_far(address + 4);

        if (colorIndex == 0)
            continue;

        uint16_t color = pgm_read_word_far(
            paletteAddress + colorIndex * sizeof(uint16_t));

        tft.fastFillRect(
            offsetX + x * scaleX,
            offsetY + y * scaleY,
            width * scaleX,
            height * scaleY,
            color);
    }
}

